CREATE TABLE IF NOT EXISTS ecosystem_certifications(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','passed','failed','revoked')),score INTEGER NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100),reviewer TEXT NOT NULL DEFAULT 'automated',evidence_json TEXT NOT NULL DEFAULT '{}',started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version));
CREATE TABLE IF NOT EXISTS ecosystem_compatibility(extension_key TEXT NOT NULL,version TEXT NOT NULL,vazincms_constraint TEXT NOT NULL,php_constraint TEXT NOT NULL,db_drivers_json TEXT NOT NULL DEFAULT '[]',dependencies_json TEXT NOT NULL DEFAULT '{}',tested_matrix_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(extension_key,version));
CREATE TABLE IF NOT EXISTS ecosystem_review_results(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT NOT NULL,check_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pass','fail','warn')),details TEXT NOT NULL DEFAULT '',evidence_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ecosystem_api_registry(api_key TEXT PRIMARY KEY,version TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'stable' CHECK(status IN('experimental','stable','deprecated','removed')),introduced_in TEXT NOT NULL,deprecated_in TEXT,remove_in TEXT,notes TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
